import { useState, useEffect, useRef, useMemo } from 'react';
import { useTheme } from '../../Common/ThemeContext';
import styles from './NavbarStyles.module.css';

function Navbar() {
  const [activeSection, setActiveSection] = useState(null);
  const scrollTimeout = useRef(null);
  const { theme } = useTheme();
  const sections = useMemo(() => ['home', 'skills', 'projects', 'contact'], []);

  useEffect(() => {
    const sectionObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      {
        threshold: 0.5,
        rootMargin: '0px 0px -50% 0px'
      }
    );

    const handleScroll = () => {
      clearTimeout(scrollTimeout.current);
      scrollTimeout.current = setTimeout(() => {
        // Scroll ended logic if needed
      }, 1500);
    };

    sections.forEach(section => {
      const element = document.getElementById(section);
      if (element) sectionObserver.observe(element);
    });

    window.addEventListener('scroll', handleScroll);

    return () => {
      sections.forEach(section => {
        const element = document.getElementById(section);
        if (element) sectionObserver.unobserve(element);
      });
      sectionObserver.disconnect();
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(scrollTimeout.current);
    };
  }, [sections]);

  return (
    <nav aria-label="Main navigation" className={`${styles.navbar} ${theme === 'dark' ? styles.dark : styles.light}`}>
      <ul>
        <li className={activeSection === 'home' ? styles.active : ''}>
          <a href="#subu">Home</a>
        </li>
        <li className={activeSection === 'skills' ? styles.active : ''}>
          <a href="#skills">Skills</a>
        </li>
        <li className={activeSection === 'projects' ? styles.active : ''}>
          <a href="#projects">Projects</a>
        </li>
        <li className={activeSection === 'contact' ? styles.active : ''}>
          <a href="#contact">Contact</a>
        </li>
      </ul>
    </nav>
  );
}

export default Navbar;
